        arr[i] = i + 1;
    }

    // Print the resized array
    printf("Resized array:\n");
    for (int i = 0; i < newSize; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Free the allocated memory
    free(arr);

    return 0;
}
